/** Describes how far `date` is from `relativeTo`, e.g. `3 hours ago` or `in 2 days`. */
export declare function relativeToDate(date: Date | number, relativeTo?: Date | number): string;
export declare function dateRange(date: Date): string;
export declare function bytes(bytes: bigint | number): string;
export declare function ms(time: number): string;
/** Formats a short duration into colon-separated values */
export declare function duration(seconds: number): string;
